<h1>Nova venda / carrinho</h1><section class="panel"><p>Selecione os produtos e quantidades. O estoque é validado novamente ao finalizar.</p><form method="post" action="?pagina=vendas&acao=finalizar"><label>Cliente<select name="cliente_id"><option value="">Consumidor não identificado</option><?php foreach($clientes as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['nome']) ?></option><?php endforeach; ?></select></label><div id="itens"><div class="cart-row"><select name="produto_id[]" required><?php foreach($produtos as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['nome']) ?> — <?= money($p['preco']) ?> (estoque: <?= (int)$p['estoque'] ?>)</option><?php endforeach; ?></select><input type="number" name="quantidade[]" min="1" value="1" required></div></div><button type="button" class="secondary" onclick="addRow()">+ Adicionar item</button><label>Pagamento<select name="pagamento"><option value="pix">Pix (2% desconto)</option><option value="dinheiro">Dinheiro (3% desconto)</option><option value="cartao">Cartão (sem desconto)</option></select></label><button type="submit">Finalizar venda</button></form></section><script>
